prompt --application/shared_components/user_interface/templates/region/ticket_stub
begin
wwv_flow_imp_shared.create_plug_template(
 p_id=>wwv_flow_imp.id(381456186317074513)
,p_layout=>'TABLE'
,p_template=>wwv_flow_string.join(wwv_flow_t_varchar2(
'<section class="amc-TTicketStub #REGION_CSS_CLASSES#" id="#REGION_STATIC_ID#" #REGION_ATTRIBUTES# aria-labelledby="#REGION_STATIC_ID#_heading">',
'  <div class="amc-TTicketStub-stub">',
'    <div class="amc-TTicketStub-stubInner">',
'      <span class="amc-TTicketStub-icon fa #ICON_CSS_CLASSES#" aria-hidden="true"></span>',
'      <h2 class="amc-TTicketStub-title" id="#REGION_STATIC_ID#_heading">#TITLE#</h2>',
'      <div class="amc-TTicketStub-actions">#HELP##EDIT##CHANGE##COPY##DELETE##CREATE#</div>',
'      <div class="amc-TTicketStub-nav">#PREVIOUS##CLOSE##NEXT#</div>',
'      <span class="amc-TTicketStub-code" aria-hidden="true"></span>',
'      <span class="amc-TTicketStub-perf" aria-hidden="true"></span>',
'    </div>',
'  </div>',
'  <div class="amc-TTicketStub-body">#BODY##SUB_REGIONS#</div>',
'</section>'))
,p_page_plug_template_name=>'AMC Ticket Stub'
,p_internal_name=>'AMC_TPL_TICKET_STUB'
,p_css_file_urls=>'#APP_FILES#amc-templates/amc-tpl-ticket-stub.css'
,p_theme_id=>42
,p_default_label_alignment=>'RIGHT'
,p_default_field_alignment=>'LEFT'
,p_translate_this_template=>'N'
,p_template_comment=>'Region template shaped like a ticket. The stub holds the region icon, the title and every button position (Help, Edit, Change, Copy, Delete, Create, then Previous, Close, Next) and a decorative barcode; a dashed perforation with punched semicircle notches separates it from the body. When the region is wide the stub sits at the start side; below about 36rem of region width it moves on top and lays out in a row, without media queries, so it adapts inside narrow columns and dialogs. Only the stub is a query container, so popups, sticky report headers and date pickers in the body are unaffected. Template options put the stub at the end side, keep it on top at every width, color it success or danger, or remove the body padding. The perforation drifts gently on hover or focus; under reduced motion it stays still. The notches are painted in the page background color, so place the region directly on the page body.'
);
end;
